def triangle_kind(a, b, c):
    x, y, z = sorted([a, b, c])
    if x <= 0 or x + y <= z:
        return "INVALID"
    square_sum = x * x + y * y
    if square_sum == z * z:
        return "RIGHT"
    if square_sum > z * z:
        return "ACUTE"
    return "OBTUSE"

