def is_prime(n):
    if n < 2:
        return False
    divisor = 2
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 1
    return True

def normalize_spaces(text):
    words = text.split()
    return " ".join(words)

def is_palindrome(text):
    cleaned = ""
    for symbol in text:
        if symbol.isalnum():
            cleaned += symbol.lower()
    return cleaned == cleaned[::-1]

def deduplicate(values):
    result = []
    seen = set()
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result

def rotate_right(values, k):
    if not values:
        return []
    k %= len(values)
    if k == 0:
        return values[:]
    return values[-k:] + values[:-k]

def second_largest(values):
    unique = sorted(set(values))
    if len(unique) < 2:
        return None
    return unique[-2]

def median(values):
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

def move_zeros(values):
    result = []
    zeros = 0
    for value in values:
        if value == 0:
            zeros += 1
        else:
            result.append(value)
    return result + [0] * zeros

def word_counts(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def most_frequent(values):
    if not values:
        return None
    counts = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    best = values[0]
    for value in values:
        if counts[value] > counts[best]:
            best = value
    return best

def group_totals(records):
    totals = {}
    for name, value in records:
        totals[name] = totals.get(name, 0) + value
    return totals

def clamp(x, left, right):
    if x < left:
        return left
    if x > right:
        return right
    return x

def gcd_nonnegative(a, b):
    a = abs(a)
    b = abs(b)
    while b != 0:
        a, b = b, a % b
    return a

